<?php $page_title='Purchases'; require_once __DIR__.'/../includes/header.php'; require_perm($pdo,'purchases','can_view'); $msg='';
$sups=$pdo->query("SELECT * FROM suppliers ORDER BY name")->fetchAll(); $whs=$pdo->query("SELECT * FROM warehouses ORDER BY name")->fetchAll(); $prods=$pdo->query("SELECT * FROM products ORDER BY name")->fetchAll();
if($_SERVER['REQUEST_METHOD']==='POST'){ verify_csrf(); $sup=(int)$_POST['supplier_id']; $wh=(int)$_POST['warehouse_id']; $pid=(int)$_POST['product_id']; $qty=(int)$_POST['quantity']; $price=(float)$_POST['unit_price']; $date=clean($_POST['purchase_date']??date('Y-m-d'));
 try{ $pdo->beginTransaction(); $total=$qty*$price; $no=gen_no('PUR'); $pdo->prepare("INSERT INTO purchases(purchase_no,supplier_id,warehouse_id,total_amount,purchase_date,created_by) VALUES(?,?,?,?,?,?)")->execute([$no,$sup,$wh,$total,$date,$_SESSION['user_id']]); $pid2=(int)$pdo->lastInsertId(); $pdo->prepare("INSERT INTO purchase_items(purchase_id,product_id,quantity,unit_price,subtotal) VALUES(?,?,?,?,?)")->execute([$pid2,$pid,$qty,$price,$total]); adjust_stock($pdo,$pid,$wh,$qty,'purchase',$no,'Purchase received'); $pdo->commit(); $msg='Purchase recorded: '.$no.' - stock added.'; audit_log($pdo,'Create Purchase','purchases',"Purchase $no total $total"); }catch(Exception $e){ $pdo->rollBack(); $msg='Error: '.e($e->getMessage()); }
}
$rows=$pdo->query("SELECT p.*, s.name as supp, w.name as wname FROM purchases p JOIN suppliers s ON s.id=p.supplier_id JOIN warehouses w ON w.id=p.warehouse_id ORDER BY p.id DESC LIMIT 100")->fetchAll();
?>
<?php if($msg): ?><div class="alert alert-info"><?= e($msg) ?></div><?php endif; ?>
<div class="row"><div class="col-md-4"><div class="card p-3"><h5>New Purchase</h5><form method="post"><?= csrf_field() ?><label class="form-label">Supplier</label><select name="supplier_id" class="form-select mb-2" required><?php foreach($sups as $s): ?><option value="<?= $s['id'] ?>"><?= e($s['name']) ?></option><?php endforeach; ?></select><label class="form-label">Warehouse (Receive Into)</label><select name="warehouse_id" class="form-select mb-2" required><?php foreach($whs as $w): ?><option value="<?= $w['id'] ?>"><?= e($w['name']) ?></option><?php endforeach; ?></select><label class="form-label">Product</label><select name="product_id" class="form-select mb-2" required><?php foreach($prods as $p): ?><option value="<?= $p['id'] ?>"><?= e($p['name']) ?> - <?= money($p['cost_price']) ?></option><?php endforeach; ?></select><label class="form-label">Quantity</label><input type="number" min="1" name="quantity" class="form-control mb-2" required><label class="form-label">Unit Price</label><input type="number" step="0.01" name="unit_price" class="form-control mb-2" required><label class="form-label">Date</label><input type="date" name="purchase_date" value="<?= date('Y-m-d') ?>" class="form-control mb-2"><button class="btn btn-primary">Record Purchase</button></form></div></div>
<div class="col-md-8"><div class="card p-3"><h5>Purchase History</h5><div class="table-responsive"><table class="table"><thead><tr><th>No</th><th>Supplier</th><th>Warehouse</th><th>Total</th><th>Date</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= e($r['purchase_no']) ?></td><td><?= e($r['supp']) ?></td><td><?= e($r['wname']) ?></td><td><?= money($r['total_amount']) ?></td><td><?= e($r['purchase_date']) ?></td></tr><?php endforeach; ?></tbody></table></div></div></div></div>
<?php require_once __DIR__.'/../includes/footer.php'; ?>
